INSERT INTO berita (id, tanggal, judul, slug, ringkasan, konten, foto_url, status, penulis) VALUES ('1', '2026-02-14', 'UMKM Rajungan di Tongas Banjir Order Jelang Imlek 2026', 'umkm-rajungan-imlek-2026', 'Sektor pengolahan hasil laut di kawasan Tongas mengalami lonjakan permintaan menjelang Tahun Baru Cina.', '<p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve; display: inline !important;"><strong>Probolinggo – Jelang Imlek 2577 Kongzili, UMKM Pengolahan Rajungan Tongas Banjir Order: Omzet Meroket hingga Rp500 Juta Per Hari, Stimulus Ekonomi Pesisir Melejit</strong></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><strong>Tongas, Probolinggo</strong> </p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Perayaan Tahun Baru Imlek 2577 Kongzili yang jatuh pada pertengahan Februari 2026 memberikan stimulus ekonomi signifikan bagi pelaku Usaha Mikro, Kecil, dan Menengah (UMKM) pengolahan rajungan di Kecamatan Tongas, Kabupaten Probolinggo. Aktivitas di sentra pengupasan rajungan di Desa Tongas Wetan meningkat pesat, dengan pesanan yang membludak hingga dua kali lipat dibandingkan hari biasa. Lonjakan permintaan ini tidak hanya mendongkrak omzet harian hingga Rp500 juta, tetapi juga memperkuat keterkaitan ekonomi yang kuat antara komoditas laut dan pendapatan masyarakat pesisir di wilayah sekitar Tongas.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Menurut laporan lapangan dari berbagai media Jatim, sentra pengolahan rajungan di Dusun Medoan (atau Me’doan/Medokan), Desa Tongas Wetan, Kecamatan Tongas, menjadi salah satu yang paling ramai. Para pekerja — mayoritas ibu rumah tangga nelayan — bekerja tanpa henti dari pagi hingga malam. Proses pengolahan dimulai dengan perebusan rajungan hingga matang sempurna, kemudian pengupasan cangkang, pemilahan daging sesuai kualitas, hingga pengemasan untuk dikirim ke pabrik ekspor maupun pasar domestik.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Salah seorang pelaku usaha, Muhammad Ridwan, pemilik UMKM pengolahan rajungan di Dusun Me’doan, mengaku produksi harian naik drastis. “Dengan jumlah produksi yang bisa sampai 5 kuintal, dalam sehari omset produksi rajungan menyentuh Rp100 juta lebih. Kadang bisa sampai Rp500 juta,” ujar Ridwan. Ia menambahkan bahwa harga daging rajungan kualitas ekspor mencapai Rp350.000 hingga Rp400.000 per kilogram, naik sekitar 20 persen menjelang Imlek.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Senada dengan itu, pengepul Misri dari Desa Tongas Wetan menyatakan, “Lonjakan pesanan mulai dirasakan sejak sebulan terakhir. Pesanan dari dalam negeri maupun luar negeri naik drastis hingga dua kali lipat dibanding hari biasa.” Permintaan datang tidak hanya dari restoran dan keluarga Tionghoa di Indonesia, melainkan juga pasar ekspor ke Cina, Amerika Serikat, dan Kanada.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Bahan baku rajungan didatangkan dari nelayan lokal di Probolinggo, Pasuruan (Lekok), Banyuwangi, hingga Madura. Namun, cuaca buruk beberapa waktu lalu sempat membuat pasokan terbatas, meski permintaan tetap tinggi. “Untuk memperoleh bahan baku rajungan, kami membeli dari nelayan Probolinggo, Pasuruan, Banyuwangi hingga Madura. Namun karena cuaca buruk, rajungan dari nelayan sulit didapat,” keluh Ridwan.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Fenomena ini menunjukkan betapa sektor perikanan rajungan tetap menjadi penopang ekonomi musiman yang handal bagi masyarakat sekitar Tongas. Puluhan ibu rumah tangga diberdayakan sebagai pekerja pengupas, dengan rata-rata penghasilan Rp1 juta hingga Rp2 juta per bulan tergantung volume pesanan. Momentum Imlek 2577 Kongzili/2026 ini menjadi “panen berkah” bagi ratusan UMKM pengolahan rajungan di wilayah pesisir Probolinggo.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Daging rajungan khas Tongas yang segar dan berkualitas tinggi memang selalu menjadi menu wajib hidangan Imlek. Selain diserap pasar lokal, sebagian besar produk olahan langsung diekspor, sehingga memberikan multiplier effect yang luas bagi perekonomian daerah.</p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;"><br></p><p dir="auto" style="background-color: rgb(255, 255, 255); white-space-collapse: preserve;">Kepala Desa Tongas Wetan dan Dinas Perikanan Kabupaten Probolinggo sebelumnya juga mencatat bahwa lonjakan permintaan Imlek selalu menjadi angin segar bagi nelayan dan pengolah rajungan. Dengan adanya stimulus ini, pelaku UMKM optimistis dapat terus meningkatkan kapasitas produksi dan memperluas jangkauan pasar di masa mendatang.</p>', 'https://assets.portal-wringinanom.web.id/legacy/imgbb-1000300351.webp', 'publish', 'Admin Desa Wringinanom');
INSERT INTO berita (id, tanggal, judul, slug, ringkasan, konten, foto_url, status, penulis) VALUES ('3fb8018d-6c53-4426-b610-7ac31fabebcb', '2026-04-10', 'Kapolsek Tongas Lakukan Sambang dan Anjangsana ke Kepala Desa Wringinanom, Pastikan Situasi Kamtibmas Tetap Kondusif Selama Bulan Ramadan', 'kapolsek-tongas-lakukan-sambang-dan-anjangsana-ke-kepala-desa-wringinanom-pastikan-situasi-kamtibmas-tetap-kondusif-selama-bulan-ramadan', 'Kapolsek Tongas AKP Ahmad Jayadi, S.H., M.H. beserta anggota Polsek Tongas melakukan kunjungan silaturahmi (sambang dan anjangsana) ke kediaman Kepala Desa Wringinanom, Saiful Rizal Habibi, serta tokoh agama Ust. Sahlan. Kegiatan ini bertujuan menjaga keamanan dan ketertiban masyarakat (kamtibmas) di Desa Wringinanom selama bulan Ramadan agar warga dapat beribadah dengan aman dan nyaman.', '<p dir="auto" style="white-space-collapse: preserve;">Probolinggo – Dalam upaya memelihara situasi keamanan dan ketertiban masyarakat yang kondusif menjelang dan selama pelaksanaan ibadah puasa Ramadan, Kapolsek Tongas AKP Ahmad Jayadi, S.H., M.H. bersama rombongan anggota Polsek Tongas melaksanakan kegiatan sambang dan anjangsana langsung ke kediaman Kepala Desa Wringinanom, Bapak Saiful Rizal Habibi, di Desa Wringinanom, Kecamatan Tongas, Kabupaten Probolinggo, pada Kamis (5/3/2026).</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">Kunjungan yang penuh kehangatan dan kekeluargaan ini juga dihadiri oleh tokoh agama setempat, Ust. Sahlan, sebagai bentuk sinergi antara aparat kepolisian, pemerintah desa, dan tokoh masyarakat dalam menciptakan lingkungan yang aman dan tenteram. Kapolsek Tongas dalam kesempatan tersebut menyampaikan apresiasi yang tinggi atas kerja sama yang telah terjalin baik antara masyarakat Desa Wringinanom dengan aparat desa dalam menjaga keamanan lingkungan sehari-hari.</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">“Kami ingin situasi kamtibmas di Desa Wringinanom tetap kondusif, sehingga masyarakat dapat menjalankan ibadah Ramadan dengan aman dan nyaman,” ujar AKP Ahmad Jayadi dengan tegas. Pernyataan ini mencerminkan komitmen Polsek Tongas untuk terus mendukung program-program pemerintah desa dalam menciptakan ketentraman bagi seluruh warga.</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">Sementara itu, Kepala Desa Wringinanom Saiful Rizal Habibi menyambut kunjungan tersebut dengan hangat dan mengucapkan terima kasih atas perhatian yang diberikan pihak kepolisian. “Kami selalu siap bekerja sama dengan pihak kepolisian untuk menjaga keamanan lingkungan,” katanya. Pernyataan ini menegaskan semangat gotong royong yang kuat antara Pemdes Wringinanom dan aparat keamanan dalam membangun desa yang maju dan aman.</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">Tokoh agama Ust. Sahlan turut menyampaikan pesan penting kepada seluruh warga Desa Wringinanom agar terus menjaga kerukunan dan persatuan serta meningkatkan keimanan dan ketaqwaan selama bulan suci Ramadan. “Bulan Ramadan adalah bulan yang penuh berkah, mari kita jadikan kesempatan ini untuk meningkatkan keimanan dan ketaqwaan kita,” imbau Ust. Sahlan.</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">Kegiatan sambang dan anjangsana ini ditutup dengan doa bersama yang dipimpin oleh tokoh agama serta penyerahan bingkisan sederhana dari pihak Polsek Tongas kepada Kepala Desa Wringinanom dan tokoh agama sebagai bentuk penghargaan atas kerjasama yang telah terjalin. Dengan adanya kegiatan ini, diharapkan situasi kamtibmas di Desa Wringinanom semakin terkendali, sehingga seluruh rangkaian ibadah Ramadan dapat berjalan lancar dan penuh berkah bagi masyarakat setempat.</p><p dir="auto" style="white-space-collapse: preserve;"><br></p>
<p dir="auto" style="white-space-collapse: preserve;">Berita ini menjadi bukti nyata komitmen aparat kepolisian dan pemerintah desa dalam membangun sinergi yang harmonis demi kemajuan dan kesejahteraan Desa Wringinanom, Kecamatan Tongas, Kabupaten Probolinggo.</p>', 'https://assets.portal-wringinanom.web.id/legacy/imgbb-Whats-App-Image2026-01-14at12-52-33-1-593135.webp', 'publish', 'Admin Desa');
INSERT INTO berita (id, tanggal, judul, slug, ringkasan, konten, foto_url, status, penulis) VALUES ('3fb8018d-6c53-4426-b610-7ac31fayhfjh', '2026-04-26', 'HALAL BIHALAL & SILATURAHMI KELUARGA BESAR MWC NU TONGAS DIGELAR DI KOPERASI MERAH PUTIH DESA WRINGINANOM', 'halal-bihalal-silaturahmi-keluarga-besar-mwc-nu-tongas-digelar-di-koperasi-merah-putih-desa-wringinanom', 'Dalam rangka mempererat tali silaturahmi pasca Hari Raya Idul Fitri 1447 H, Keluarga Besar Majelis Wakil Cabang Nahdlatul Ulama (MWC NU) Tongas', 'Wringinanom, 26 April 2026 – Dalam rangka mempererat tali silaturahmi pasca Hari Raya Idul Fitri 1447 H, Keluarga Besar Majelis Wakil Cabang Nahdlatul Ulama (MWC NU) Tongas mengadakan acara Halal Bihalal dan Silaturahmi di Koperasi Merah Putih Desa Wringinanom.
Acara yang berlangsung mulai pukul 08.00 WIB ini diawali dengan pembagian sembako kepada warga sebagai bentuk kepedulian sosial. Kemudian dilanjutkan dengan silaturahmi dan halal bihalal yang penuh kehangatan dan kebersamaan.
Hadir dalam acara tersebut para pengurus MWC NU Tongas, anggota badan otonom (banom) NU, serta seluruh keluarga besar NU Tongas. Suasana pagi itu terasa sangat khidmat, di mana para peserta saling memaafkan, bertukar kabar, dan memperkuat ukhuwah Islamiyah di antara sesama.
Kepala Desa Wringinanom menyambut baik terselenggaranya acara ini di wilayah desa. “Halal bihalal seperti ini sangat penting untuk menjaga persaudaraan dan keharmonisan antar warga, khususnya di lingkungan keluarga besar NU,” ujarnya.
Acara ini diharapkan dapat menjadi momentum untuk terus memperkuat kerukunan dan gotong royong di Desa Wringinanom. Semoga segala kegiatan positif seperti ini selalu membawa berkah dan manfaat bagi kemajuan desa.
Terima kasih kepada seluruh panitia dan peserta yang telah hadir serta mendukung terselenggaranya acara ini. Semoga Allah SWT senantiasa memberikan ampunan, berkah, dan rahmat-Nya kepada kita semua. Amin.', 'https://assets.portal-wringinanom.web.id/legacy/imgbb-1777195764263.webp', 'publish', 'Admin Desa');
