INSERT INTO apbdes (tahun_anggaran, total_pendapatan, total_belanja, silpa, pend_dana_desa, pend_add, pend_bantuan_kab, pend_bagi_hasil, pend_pades, pend_lain_lain, bel_pembangunan, bel_pemerintahan, bel_pembinaan, bel_bencana, bel_pemberdayaan, pembiayaan_penerimaan, pembiayaan_pengeluaran, pembiayaan_netto, file_pdf, tanggal_disahkan, nama_pengesah) VALUES ('2025', 2424711315.98, 2129718492, 26057003.33, 1466878000, 471753555, 400000000, 75252180, 10000000, 827580.98, 1203384900, 708532164, 92380714, 66100000, 59320714, 27970179.35, 296906000, -268935820.65, 'link_apbdes_2025.pdf', '31/12/2025', 'Gak tau');INSERT INTO berita (id, tanggal, judul, slug, ringkasan, konten, foto_url, status, penulis) VALUES (
  '1b451ade-2933-4bab-b122-75a073560304',
  '30 Agustus 2026',
  'Semarak HUT RI ke-81: Karnaval Budaya Desa Wringinanom Berlangsung Meriah dan Penuh Kekeluargaan',
  'semarak-hut-ri-ke-81-karnaval-budaya-desa-wringinanom',
  'Pawai Budaya dan Karnaval Desa Wringinanom digelar meriah dalam rangka HUT ke-81 Kemerdekaan RI dan diikuti ribuan warga dari seluruh dusun/RW se-Desa Wringinanom, Kecamatan Tongas. Kegiatan ini menjadi sarana mempererat kerukunan dan gotong royong sekaligus menggerakkan perekonomian warga.',
  '<p><strong>WRINGINANOM, TONGAS</strong> – Dalam rangka memperingati Hari Ulang Tahun (HUT) ke-81 Kemerdekaan Republik Indonesia, Pemerintah Desa Wringinanom bersama seluruh elemen masyarakat menggelar Pawai Budaya dan Karnaval Desa pada Minggu (30/08/2026). Kegiatan ini menjadi puncak perayaan kemerdekaan yang diikuti oleh ribuan warga dari seluruh dusun/RW se-Desa Wringinanom, Kecamatan Tongas, Kabupaten Probolinggo.</p><p>Sejak pagi hari, antusiasme masyarakat sudah tampak memadati titik kumpul dan sepanjang rute yang dilintasi rombongan pawai, mulai dari jalan poros desa hingga ruas Jalan Raya Tongas–Lumbang. Beragam kreasi ditampilkan oleh para peserta, mulai dari busana adat nusantara, kostum kreasi tematik, tarian daerah, teatrikal perjuangan, hingga arak-arakan replika kesenian lokal.</p><h2>Perkuat Kerukunan dan Gotong Royong</h2><p>Kepala Desa Wringinanom menyampaikan apresiasi setinggi-tingginya kepada seluruh panitia, tokoh masyarakat, pemuda karang taruna, dan seluruh warga yang telah berpartisipasi aktif mempersiapkan kegiatan ini secara swadaya.</p><blockquote>"Karnaval ini bukan sekadar hiburan tahunan, melainkan wujud rasa syukur atas kemerdekaan serta sarana mempererat kerukunan, persatuan, dan gotong royong antarwarga di Desa Wringinanom. Terima kasih kepada seluruh masyarakat yang tetap menjaga ketertiban sehingga acara berjalan lancar dan aman," ungkap Kepala Desa.</blockquote><h2>Menggerakkan Perekonomian Warga</h2><p>Selain menyuguhkan hiburan seni dan budaya, kegiatan pawai desa ini turut memberikan dampak positif terhadap perputaran ekonomi warga setempat. Keberadaan ribuan penonton di sepanjang rute memberikan ruang berkah bagi para pelaku UMKM dan pedagang kaki lima dari Desa Wringinanom untuk menjajakan aneka kuliner dan minuman.</p><p>Pemerintah Desa Wringinanom juga mengapresiasi peran Linmas, Babinsa, dan Bhabinkamtibmas Kecamatan Tongas yang telah bersinergi mengawal jalannya acara dan mengatur arus lalu lintas di jalur Tongas–Lumbang, sehingga acara berlangsung tertib hingga barisan peserta terakhir mencapai garis akhir.</p>',
  'https://assets.portal-wringinanom.web.id/berita/hut-81-karnaval-budaya.webp',
  'publish',
  'Pemerintah Desa Wringinanom'
);

